        const moveSnake = () =>{
            snake.unshift({x: snake[0].x + direction.x, y: snake[0].y + direction.y});
            if (snake[0].x === food.x && snake[0].y === food.y){
                score = score + 1; food.x = Math.floor(Math.random() * tileCount);
                food.y = Math.floor(Math.random() * tileCount);
            }
            else if(!(snake[0].x === food.x && snake[0].y === food.y)){
                snake.pop();
            }
        }

        const endGame = () =>{
            if ((snake[0].x >= tileCount || snake[0].y >= tileCount) || (snake[0].x < 0 || snake[0].y < 0)){
                snake.length = 0;
                lose = true;
            }
        }

        const restartGame = () =>{
            lose = false;
            score = 0;
            snake = [
                { x: 10, y: 10 },
                { x: 9, y: 10 },
                { x: 8, y: 10 }
            ];
            document.getElementById("gameCanvas").style.display = "block";
            document.getElementById("gameover").style.display = "none";
